#include "document.h"
#include "background_layer.h"
#include "project_encode.h"
#include "project_import.h"
#include <iostream>
using namespace moon;
static void check(bool v,const char* m){if(!v)throw std::runtime_error(m);}
int main(){try{
 Document d(4,3);const auto active=d.layer().id;d.addLinkedFrame();const auto frame=d.frame().id;const auto selected=d.timelineSelection().layers;timeline::Surface tile;tile.width=2;tile.height=2;tile.pixels={0xff112233,0x00445566,0xff778899,0xffaabbcc};const auto h=d.historySize();check(d.createBackgroundLayer(tile),"Create PNG background");const auto bg=d.timeline().state().layers.back().id;check(d.layer().id==active&&d.frame().id==frame&&d.timelineSelection().layers==selected,"Creation preserves editor target");check(d.historySize()==h+1&&!d.timeline().state().layers.back().locked,"One history entry, unlocked");const auto& state=d.timeline().state();const auto* first=d.timeline().findCel(bg,state.frames[0].id);const auto* second=d.timeline().findCel(bg,state.frames[1].id);check(first&&second&&d.timeline().resolveSurface(first->id).source->id==d.timeline().resolveSurface(second->id).source->id,"Frames share background owner");const auto firstId=first->id;check(d.resizeCanvas(1,1,CanvasAnchor::NorthWest),"Crop canvas");check(d.resizeCanvas(6,5,CanvasAnchor::NorthWest),"Grow canvas");const auto surface=d.timeline().resolveSurface(firstId).surface;check(surface&&surface->width>=6&&surface->height>=5&&surface->pixels[5]==tile.pixels[1],"Full repeat retained across tiny crop");d.undo();check(d.width()==1&&d.height()==1,"Resize undo");d.redo();check(d.width()==6&&d.height()==5,"Resize redo");auto encoded=project::encodeEditableProject(d);auto imported=project::prepareEditableImport(project::readProjectManifest(encoded.bytes));check(imported.timeline.layers.back().background&&imported.timeline.layers.back().background->repeatWidth==2,"Project retains background metadata");
 d.selectLayer(active);d.beginStroke({0,0},0x80123456);d.commitStroke();const auto pixels=d.pixels();check(d.setLayerBackground(active,true),"Convert ordinary to background");check(d.layer().id==active&&d.timeline().state().layers.back().id==active&&!d.layer().locked&&d.pixels()==pixels,"Conversion preserves pixels lock and focus, moves root bottom");d.undo();check(!d.layer().background&&d.pixels()==pixels,"Convert undo");d.redo();check(d.layer().background.has_value(),"Convert redo");check(d.setLayerBackground(active,false)&&!d.layer().background,"Convert back to ordinary");
 check(backgroundPatternColor("solid",0,0)==0xffe4e4e4,"Legacy solid default");std::cout<<"Background creation/conversion/history/linked ownership/repeat/project checks passed\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}

